    {"id": "thermoqa-v0-4-composite", "name": "ThermoQA v0.4 — Composite", "domain": "Nuclear Engineering", "file": "thermoqa_v0_4_composite_external.csv", "score": "Composite", "release": "2026-03-25", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/olivenet-iot/ThermoQA", "summary": {"en": "ThermoQA measures open numerical thermodynamics, thermofluids, and power-cycle reasoning.", "zh": "ThermoQA 衡量开放式工程热力学、热流体和动力循环数值推理能力。"}, "task_format": {"en": "The model solves 293 property, component, and cycle-analysis problems without tools.", "zh": "模型在不使用工具的情况下解决 293 道物性、部件和循环分析问题。"}, "scoring": {"metric_name": "Question-count-weighted composite", "explanation": {"en": "Tier 1 property accuracy and weighted Tier 2–3 step accuracy are combined using their question counts.", "zh": "Tier 1 物性准确率与 Tier 2–3 加权步骤准确率按各层题量合并。"}}, "evaluation_target": "process_and_output", "protocol": "ThermoQA v0.4 fixed 293-question zero-shot, single-query, no-tool protocol; three runs and published tolerance rules."},
    {"id": "medagentbench-v1-overall-sr", "name": "MedAgentBench v1 — Overall", "domain": "Biomedical Engineering", "file": "medagentbench_v1_overall_external.csv", "score": "Success rate", "release": "2025-01-24", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/stanfordmlgroup/MedAgentBench", "summary": {"en": "MedAgentBench evaluates agents on physician-authored workflows in a simulated FHIR electronic-health-record environment.", "zh": "MedAgentBench 在模拟 FHIR 电子病历环境中评估 agent 完成医生编写 workflow 的能力。"}, "task_format": {"en": "The agent completes 300 retrieval, documentation, ordering, and conditional-action tasks using nine FHIR functions in at most eight rounds.", "zh": "agent 使用九个 FHIR function，在最多八轮内完成 300 个检索、记录、医嘱和条件操作 task。"}, "scoring": {"metric_name": "Overall task success rate", "explanation": {"en": "The score is the fraction of 300 tasks passing the fixed reference-answer or rule-based action checks.", "zh": "分数是 300 个 task 中通过固定参考答案或规则化 action check 的比例。"}}, "evaluation_target": "environment_outcome", "protocol": "MedAgentBench paper-v2 fixed 300 tasks, simple orchestrator, nine FHIR functions, eight-round limit, pass@1."},
    {"id": "medcalc-bench-paper1047", "name": "MedCalc-Bench Paper-1047", "domain": "Biomedical Engineering", "file": "medcalc_bench_paper1047_external.csv", "score": "Accuracy", "release": "2024-06-17", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/ncbi-nlp/MedCalc-Bench", "summary": {"en": "MedCalc-Bench tests calculation-grounded clinical decision support across 55 medical calculators.", "zh": "MedCalc-Bench 使用 55 类医学计算器测试以计算为基础的临床决策支持能力。"}, "task_format": {"en": "Given a patient note and request, the model extracts variables and returns a numeric, date, risk, severity, or diagnostic result.", "zh": "模型根据患者记录和请求抽取变量，并输出数值、日期、风险、严重度或诊断结果。"}, "scoring": {"metric_name": "Micro accuracy", "explanation": {"en": "The score is accuracy over the paper's 1,047 cases using exact or published 5%-tolerance checks.", "zh": "分数是在论文固定 1,047 个病例上，按精确匹配或规定的 5% 容差计算的正确率。"}}, "evaluation_target": "final_output", "protocol": "MedCalc-Bench paper 1,047-case set, one-shot chain-of-thought, one curated calculator-specific exemplar, final-answer scoring."},
    {"id": "mediconfusion-v2-mc", "name": "MediConfusion v2 — MC Set Accuracy", "domain": "Biomedical Engineering", "file": "mediconfusion_v2_mc_external.csv", "score": "Set accuracy", "release": "2024-09-23", "floor": 0.25, "ceiling": 1.0, "source": "https://github.com/mshahabsepehri/mediconfusion", "summary": {"en": "MediConfusion tests whether multimodal models distinguish deliberately confusing pairs of medical images.", "zh": "MediConfusion 测试多模态模型能否区分刻意构造的易混淆医学影像对。"}, "task_format": {"en": "The model answers the same binary question on both images in each of 176 pairs with opposite correct answers.", "zh": "模型对 176 组影像中的两张图回答同一道二选一问题，而两张图的正确答案相反。"}, "scoring": {"metric_name": "Pair-level MC set accuracy", "explanation": {"en": "A pair is correct only when both binary answers are correct; chance pair accuracy is 25%.", "zh": "只有一组中的两个二元答案都正确，该组才计分；随机组准确率为 25%。"}}, "evaluation_target": "final_output", "protocol": "MediConfusion v2 fixed 176-pair multiple-choice protocol; set accuracy only. Free-form, prefix, confusion, and individual-answer metrics are excluded."},
    {"id": "fdm-bench-v1-gcode-deterministic", "name": "FDM-Bench — G-code Detection", "domain": "Manufacturing", "file": "fdm_bench_v1_gcode_external.csv", "score": "Accuracy", "release": "2024-12-13", "floor": 0.25, "ceiling": 1.0, "source": "https://github.com/AhmadrezaNia/FDM-Bench", "summary": {"en": "FDM-Bench tests anomaly diagnosis from full fused-deposition-manufacturing G-code files.", "zh": "FDM-Bench 测试模型根据完整熔融沉积制造 G-code 文件诊断打印异常的能力。"}, "task_format": {"en": "Given a G-code file and printer context, the model chooses normal, under-extrusion, over-extrusion, or spaghetti failure.", "zh": "模型根据 G-code 文件和打印机 context，在正常、挤出不足、挤出过量或意大利面式失败中选择一个标签。"}, "scoring": {"metric_name": "Exact-label accuracy", "explanation": {"en": "The score is exact four-class accuracy on the fixed 16-file deterministic set.", "zh": "分数是固定 16 个文件上的四分类精确准确率。"}}, "evaluation_target": "final_output", "protocol": "FDM-Bench v1 deterministic 16-file G-code anomaly task, temperature 0; subjective ratings and probability outputs are excluded."},
    {"id": "isafetybench-2025-single-avg", "name": "iSafetyBench — Single Accuracy", "domain": "Manufacturing", "file": "isafetybench_2025_single_avg_external.csv", "score": "Average accuracy", "release": "2025-08-01", "floor": 0.0625, "ceiling": 1.0, "source": "https://github.com/iSafetyBench/data", "summary": {"en": "iSafetyBench evaluates action recognition in routine and hazardous industrial videos.", "zh": "iSafetyBench 评估模型识别正常与危险工业视频中动作的能力。"}, "task_format": {"en": "The model watches a 4–8 second industrial clip and selects the correct action from 16 options.", "zh": "模型观看 4–8 秒工业视频，并从 16 个选项中选择正确动作。"}, "scoring": {"metric_name": "Normal/hazard mean single-label accuracy", "explanation": {"en": "The score is the unweighted mean of exact single-label accuracy on 680 normal and 420 hazard clips.", "zh": "分数是 680 个正常视频与 420 个危险视频的精确单标签准确率的等权平均。"}}, "evaluation_target": "final_output", "protocol": "iSafetyBench 2025 fixed 1,100-video zero-shot single-label protocol; multi-label metrics are excluded."},
    {"id": "fle-neurips-2025-planning", "name": "Factorio Learning Environment — Planning", "domain": "Manufacturing", "file": "fle_neurips2025_planning_external.csv", "score": "Planning success", "release": "2025-03-06", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/JackHopkins/factorio-learning-environment", "summary": {"en": "FLE Planning evaluates long-horizon factory design, production logistics, and resource optimization in Factorio.", "zh": "FLE Planning 在 Factorio 中评估长链工厂设计、生产物流与资源优化能力。"}, "task_format": {"en": "Using a stateful Python REPL and fixed API, the agent builds automatic factories for 24 products under a 128-interaction horizon.", "zh": "agent 通过有状态 Python REPL 和固定 API，在 128 次 interaction 内为 24 种产品建设自动工厂。"}, "scoring": {"metric_name": "Repeated-run planning success", "explanation": {"en": "The score is task completion averaged over eight runs per product using the published throughput holdout.", "zh": "分数按每种产品八次运行的 task 完成率计算，并使用论文规定的产量 holdout。"}}, "evaluation_target": "environment_outcome", "protocol": "NeurIPS 2025 FLE Lab-Play Planning, Factorio 1.1.110, 24 products, 128 interactions, eight runs, temperature 0.5."},
    {"id": "feabench-gold-modelspecs-oneshot", "name": "FEABench Gold — Executability", "domain": "Computational Engineering", "file": "feabench_gold_modelspecs_oneshot_external.csv", "score": "Executability", "release": "2025-04-08", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/google/feabench", "summary": {"en": "FEABench tests generation of executable COMSOL finite-element simulation models from engineering specifications.", "zh": "FEABench 测试模型根据工程规格生成可执行 COMSOL 有限元仿真模型的能力。"}, "task_format": {"en": "For 15 verified problems, the model receives complete model specifications and one example, then writes COMSOL Java API calls.", "zh": "对 15 个验证任务，模型获得完整建模规格和一个示例，再生成 COMSOL Java API 调用。"}, "scoring": {"metric_name": "Mean statement executability", "explanation": {"en": "Each task scores the fraction of parsed API statements that execute correctly, averaged over the Gold set.", "zh": "每题按解析出的 API 语句中可正确执行的比例计分，再在 Gold set 上取平均。"}}, "evaluation_target": "process_and_output", "protocol": "FEABench Gold 15 tasks, ModelSpecs input, one-shot prompting, paper-v1 executability metric; Valid Target and other prompt variants are excluded."},
    {"id": "cfdcodebench-v1-zeroshot", "name": "CFDCodeBench — Zero-shot", "domain": "Computational Engineering", "file": "cfdcodebench_v1_zeroshot_external.csv", "score": "Success rate", "release": "2025-09-19", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/NLR-Theseus/cfdllmbench", "summary": {"en": "CFDCodeBench evaluates generation of executable, numerically accurate, convergent CFD and PDE solvers.", "zh": "CFDCodeBench 评估模型生成可执行、数值准确且具备收敛性的 CFD 与 PDE solver 的能力。"}, "task_format": {"en": "Given a structured PDE specification, the model writes a complete Python solver for each of 24 tasks.", "zh": "模型根据结构化 PDE 规格，为 24 个 task 分别生成完整 Python solver。"}, "scoring": {"metric_name": "Strict solver success rate", "explanation": {"en": "A task passes only if code executes, normalized MSE is at most 10%, and error falls under spatial and temporal refinement.", "zh": "只有代码可执行、归一化 MSE 不超过 10%，且空间和时间网格加密后误差下降，task 才通过。"}}, "evaluation_target": "environment_outcome", "protocol": "CFDCodeBench fixed 24 tasks, standard zero-shot, 60-second sandbox timeout, strict execution/accuracy/convergence success."},
    {"id": "fem-bench-2025-first-run", "name": "FEM-Bench 2025 — First Run", "domain": "Computational Engineering", "file": "fem_bench_2025_first_run_external.csv", "score": "Function correctness", "release": "2025-12-23", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/elejeune11/FEM-bench", "summary": {"en": "FEM-Bench tests first-attempt scientific Python implementations for finite-element and structural-analysis tasks.", "zh": "FEM-Bench 测试模型首次生成有限元与结构分析 scientific Python 实现的能力。"}, "task_format": {"en": "The model completes one numerical function for each of 33 FEM and structural-analysis tasks.", "zh": "模型为 33 个有限元与结构分析 task 分别补全一个数值函数。"}, "scoring": {"metric_name": "First-run function correctness", "explanation": {"en": "A task passes only if the first function parses, executes, uses allowed imports, and passes every hidden numerical check.", "zh": "只有首次生成的函数可解析、可执行、仅用允许的 import，并通过全部隐藏数值检查，task 才通过。"}}, "evaluation_target": "environment_outcome", "protocol": "FEM-Bench 2025 fixed 33 tasks, first run only, temperature 0.1, first parsed function, all hidden checks required."},
    {"id": "gs-powerflow-100-proctext", "name": "GS-PowerFlow-100 — Procedural Text", "domain": "Energy & Infrastructure", "file": "gs_powerflow_100_proctext_external.csv", "score": "Within 5%", "release": "2026-05-18", "floor": 0.0, "ceiling": 1.0, "source": "https://arxiv.org/html/2605.18642", "summary": {"en": "GS-PowerFlow-100 tests manual numerical power-flow reasoning on three-bus AC systems.", "zh": "GS-PowerFlow-100 测试模型在三节点交流系统上手工进行数值潮流计算的能力。"}, "task_format": {"en": "Without tools, the model follows a Gauss–Seidel procedure and reports converged slack-bus real or reactive power for 100 cases.", "zh": "模型不使用工具，按 Gauss–Seidel 过程求解 100 个案例，并输出收敛后的平衡节点有功或无功功率。"}, "scoring": {"metric_name": "Cases below 5% relative error", "explanation": {"en": "The score is the fraction of 100 cases whose first parsed requested power value has relative error below 5%.", "zh": "分数是 100 个案例中，首次解析出的目标功率值相对误差低于 5% 的比例。"}}, "evaluation_target": "process_and_output", "protocol": "GS-PowerFlow fixed 100-case replication, procedural-text prompt, no tools, one run per case, strict <5% relative-error success."},
    {"id": "climaqa-gold-mcq-default", "name": "ClimaQA-Gold — Default MCQ", "domain": "Earth Science", "file": "climaqa_gold_mcq_default_external.csv", "score": "Accuracy", "release": "2024-10-22", "floor": 0.25, "ceiling": 1.0, "source": "https://github.com/Rose-STL-Lab/genie-climaqa", "summary": {"en": "ClimaQA-Gold evaluates graduate-level climate-science knowledge and reasoning on expert-validated questions.", "zh": "ClimaQA-Gold 使用专家验证题目评估研究生层级气候科学知识与推理能力。"}, "task_format": {"en": "The model selects one of four answers for 245 validated Base, Reasoning, and Hypothetical climate questions.", "zh": "模型回答 245 道通过验证的四选一气候题，覆盖 Base、Reasoning 和 Hypothetical。"}, "scoring": {"metric_name": "Three-trial exact accuracy", "explanation": {"en": "The score is mean exact-choice accuracy over three full trials on rows with Validation=True.", "zh": "分数是在 Validation=True 的题目上完成三次完整试验后的平均选项准确率。"}}, "evaluation_target": "final_output", "protocol": "ClimaQA-Gold pinned 245 validated MCQs, default no-context prompt, top output token, three trials; invalid, Silver, freeform, RAG, and adaptation variants are excluded."},
    {"id": "tps-calcbench-v1-core-exact", "name": "TPS-CalcBench — Core Exact", "domain": "Mechanical & Aerospace Engineering", "file": "tps_calcbench_v1_core_exact_external.csv", "score": "Exact accuracy", "release": "2026-04-20", "floor": 0.0, "ceiling": 1.0, "source": "https://arxiv.org/html/2604.17966", "summary": {"en": "TPS-CalcBench evaluates analytical calculations for hypersonic thermal-protection systems and high-temperature gas dynamics.", "zh": "TPS-CalcBench 评估高超声速热防护系统和高温气体动力学解析工程计算能力。"}, "task_format": {"en": "The model solves 420 core engineering problems, shows calculation steps, and returns a final numerical answer with units.", "zh": "模型解决 420 道核心工程计算题，展示计算步骤，并给出带单位的最终数值答案。"}, "scoring": {"metric_name": "Core exact outcome accuracy", "explanation": {"en": "A response is exact when its extracted numerical result has under 1% relative error; missing outputs remain wrong over the full 420-item denominator.", "zh": "提取数值的相对误差低于 1% 时计为 Exact；缺失输出按错误处理，分母始终是完整 420 题。"}}, "evaluation_target": "process_and_output", "protocol": "TPS-CalcBench arXiv-v1 420-item high-confidence core, Track A, zero-shot standardized prompt, no tools/RAG/fine-tuning, exact <1% accuracy."},
    {"id": "chipbench-v2-verilog-generation-pass1", "name": "ChipBench v2 — Verilog Pass@1", "domain": "Electrical Engineering", "file": "chipbench_v2_verilog_pass1_external.csv", "score": "Pass@1", "release": "2026-01-29", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/zhongkaiyu/ChipBench", "summary": {"en": "ChipBench evaluates generation of structurally complex, simulation-verified Verilog hardware modules.", "zh": "ChipBench 评估模型生成结构复杂、通过仿真验证的 Verilog 硬件模块的能力。"}, "task_format": {"en": "Given a hardware specification and supplied interfaces, the model writes a complete implementation for one of 44 modules.", "zh": "模型根据硬件规格和提供的接口，为 44 个模块之一生成完整实现。"}, "scoring": {"metric_name": "Macro-average Verilog generation Pass@1", "explanation": {"en": "Pass@1 estimates one-sample compile-and-test success; the headline is the unweighted mean across CPU-IP, hierarchical, and self-contained categories.", "zh": "Pass@1 估计单次生成通过编译和全部测试的概率；headline 是 CPU-IP、层次模块和独立模块三个类别的非加权平均。"}}, "evaluation_target": "environment_outcome", "protocol": "ChipBench arXiv-v2 fixed 44 Verilog-generation modules, single model, temperature 0.85, top-p 0.95, paper Average Pass@1; debugging, MAGE and Pass@k are excluded."},
    {"id": "circuit-v1-zeroshot-global", "name": "CIRCUIT — Zero-shot Global", "domain": "Electrical Engineering", "file": "circuit_v1_zeroshot_global_external.csv", "score": "Accuracy", "release": "2025-02-11", "floor": 0.0, "ceiling": 1.0, "source": "https://arxiv.org/html/2502.07980", "summary": {"en": "CIRCUIT evaluates numerical reasoning over basic, analog, power, and RF circuit problems.", "zh": "CIRCUIT 评估模型解决基础、模拟、电力和射频电路数值问题的能力。"}, "task_format": {"en": "The model inspects a circuit problem and diagram, then returns a numerical answer to six decimal places.", "zh": "模型阅读电路题和电路图，再给出保留六位小数的数值答案。"}, "scoring": {"metric_name": "Global numerical-answer accuracy", "explanation": {"en": "The score is the fraction of 510 questions whose parsed answer differs from ground truth by less than 0.001.", "zh": "分数是 510 道题中，解析答案与标准答案绝对误差小于 0.001 的比例。"}}, "evaluation_target": "final_output", "protocol": "CIRCUIT v1 fixed 510 questions, plain zero-shot with diagrams, no netlist, global <0.001 absolute-error accuracy; one-shot and template-pass metrics are excluded."},
    {"id": "picbench-v1-baseline-functional-pass1", "name": "PICBench — Baseline Functional Pass@1", "domain": "Electrical Engineering", "file": "picbench_v1_baseline_pass1_external.csv", "score": "Pass@1", "release": "2025-02-05", "floor": 0.0, "ceiling": 1.0, "source": "https://github.com/PICDA/PICBench", "summary": {"en": "PICBench evaluates simulation-ready photonic integrated-circuit netlist generation.", "zh": "PICBench 评估模型生成可仿真的光子集成电路 netlist 的能力。"}, "task_format": {"en": "Given a PIC specification and SAX API, the model generates a JSON netlist of components, parameters, ports, and connections.", "zh": "模型根据 PIC 规格和 SAX API，生成包含器件、参数、端口和连接的 JSON netlist。"}, "scoring": {"metric_name": "Baseline functional Pass@1", "explanation": {"en": "A sample passes only when it executes in SAX and its frequency response agrees with the expert golden design; Pass@1 uses five samples per task.", "zh": "只有 netlist 在 SAX 中可执行且频率响应与专家 golden design 一致时才通过；Pass@1 使用每题五次样本估计。"}}, "evaluation_target": "environment_outcome", "protocol": "PICBench v1 fixed 24 tasks, baseline API prompt, zero feedback, five samples, functional Pass@1; restrictions, feedback, syntax-only and Pass@5 are excluded."},
    {"id":"pubmedqa-pqal-test500-zero-shot","name":"PubMedQA — PQA-L Test 500","file":"pubmedqa_pqal_test500_external.csv","score":"Accuracy","release":"2019-09-13","floor":0.333,"ceiling":1.0,"source":"https://github.com/pubmedqa/pubmedqa","summary":{"en":"PubMedQA measures biomedical evidence reasoning over expert-labelled PubMed questions.","zh":"PubMedQA 使用专家标注的 PubMed 问题评估生物医学证据推理。"},"task_format":{"en":"Given a research question and abstract without its conclusion, select yes, no, or maybe.","zh":"给定研究问题及去掉结论的摘要，选择 yes、no 或 maybe。"},"scoring":{"metric_name":"Mean exact-choice accuracy","explanation":{"en":"Exact accuracy on the fixed 500-question PQA-L test split, averaged across ten zero-shot runs.","zh":"固定 500 题 PQA-L test split 的精确选择准确率，取十次 zero-shot 运行均值。"}},"evaluation_target":"final_output","protocol":"PQA-L expert-labelled 500-question test split, Inspect AI zero-shot direct choice, ten runs; other PubMedQA splits and fine-tuned results excluded."},
